// CloudIT Operations Portal — Phase 6 database metrics collector.
//
// Computes the shared time constants for the run. All timestamps are computed
// at RUN TIME — never hardcode a test clock: publishedAt must be within
// ±5 minutes of ingestion (0004 stale_timestamp).
//
// The sampling window is the CURRENT 15-minute bucket (floor to :00/:15/:30/:45)
// and the idempotency bucket is the same window rendered as YYYY-MM-DDTHHMM in
// UTC (opaque; only uniqueness matters). freshUntil is observedAt + 1800s, the
// seeded 30-minute freshness for the 15-minute PostgreSQL metrics.

const now = new Date();
const nowMs = now.getTime();
const WINDOW_MS = 15 * 60 * 1000;
const windowStart = new Date(Math.floor(nowMs / WINDOW_MS) * WINDOW_MS);
const windowEnd = new Date(windowStart.getTime() + WINDOW_MS);
const pad = (n) => String(n).padStart(2, '0');
const bucket =
  windowStart.getUTCFullYear() + '-' + pad(windowStart.getUTCMonth() + 1) + '-' +
  pad(windowStart.getUTCDate()) + 'T' + pad(windowStart.getUTCHours()) + pad(windowStart.getUTCMinutes());

return [{
  json: {
    projectRef: 'kcnsztexllifcjurvtvz',
    windowStart: windowStart.toISOString(),
    windowEnd: windowEnd.toISOString(),
    observedAt: now.toISOString(),
    publishedAt: now.toISOString(),
    freshUntil: new Date(nowMs + 1800 * 1000).toISOString(),
    bucket
  }
}];

// CloudIT Operations Portal — Phase 6 database metrics collector (CRITICAL NODE).
//
// LIVE-FORMAT NOTE (2026-09-14): the Supabase analytics metrics endpoint returns
// PROMETHEUS TEXT EXPOSITION FORMAT — one big string of lines:
//   # HELP [name] [doc]          [- comments, skipped
//   # TYPE [name] [type]         [- comments, skipped
//   [name]{label="v",...} 1      [- a sample: series name, optional labels, value
//   [name] 9.883792e+06          [- samples may omit labels
// This parser reads EVERY sample into name -] latest value, then maps the 13
// seeded metric_keys. A seeded metric whose series is absent resolves to null
// and is OMITTED from the batch (we never guess) — absence shows as NO_DATA
// in the portal, never as a wrong number, and can never poison the batch.
//
// CONFIRMED LIVE 2026-09-14 against the real endpoint response:
// - pg_database_size_bytes is PER-DATABASE ({datname="..."} label): postgres,
//   template0, template1. The seeded metric is the TOTAL, so every sample of
//   the series is SUMMED (last-sample-wins would report one ~7.5 MB template
//   DB instead of the ~87 MB total; Supabase dashboard shows 91 MB).
// - pgbouncer_config_max_client_connections exists (value 200) — feeds
//   pgbouncer_max_clients and pgbouncer_utilization_percent.
// The node's `seriesFound.allNames` output lists every series the endpoint
// returned — compare against SERIES_MAP to correct any future mismatch.

const text = $input.first().json.data;
const config = $('Load Config').first().json;

// --- Prometheus text parser -------------------------------------------------
// Robust to label commas, escaped quotes, and scientific-notation values.
const samples = {};
let dbSizeBytesSum = 0; // pg_database_size_bytes is per-datname — sum ALL samples
if (typeof text === 'string' && text.length > 0) {
  for (const rawLine of text.split('\n')) {
    const line = rawLine.trim();
    if (line === '' || line.startsWith('#')) continue;
    const m = line.match(/^([a-zA-Z_:][a-zA-Z0-9_:]*)(?:\{[^}]*\})?\s+(-?[0-9.eE+-]+)(?:\s+\d+)?$/);
    if (!m) continue;
    const value = parseFloat(m[2]);
    if (!Number.isFinite(value)) continue;
    if (m[1] === 'pg_database_size_bytes') {
      dbSizeBytesSum += value; // total across every datname
      continue;
    }
    samples[m[1]] = value; // last sample wins (aggregate series)
  }
}

// --- SERIES_MAP: seeded metric_key -] candidate series names (first hit wins)
const SERIES_MAP = {
  'postgresql.up': ['pg_up'],
  'postgresql.connections_direct': ['pg_stat_database_num_backends', 'pg_stat_activity_count'],
  'postgresql.connections_supavisor': ['supavisor_connections_active', 'supavisor_pool_connections'],
  // CONFIRMED LIVE 2026-09-14: pgbouncer_used_clients exists in the response.
  'postgresql.connections_pgbouncer': ['pgbouncer_used_clients', 'pgbouncer_pools_client_active_connections'],
  'postgresql.pgbouncer_max_clients': ['pgbouncer_config_max_client_connections'],
  'postgresql.waiting_connections': ['pgbouncer_pools_client_waiting_connections', 'pgrst_db_pool_requests_waiting'],
  'postgresql.filesystem_read_only': ['node_filesystem_readonly'],
  'postgresql.oom_kill_count': ['node_vmstat_oom_kill'],
};

function pick(candidates) {
  for (const name of candidates) {
    if (Object.prototype.hasOwnProperty.call(samples, name)) return samples[name];
  }
  return null;
}

// --- Resolve direct metrics --------------------------------------------------
const resolved = {};
for (const [metricKey, candidates] of Object.entries(SERIES_MAP)) {
  resolved[metricKey] = pick(candidates);
}
resolved['postgresql.database_size_bytes'] =
  dbSizeBytesSum > 0 ? dbSizeBytesSum : (samples['pg_database_size_bytes'] ?? null);

// PgBouncer utilization = used clients / configured max (percent, 1 decimal).
{
  const used = resolved['postgresql.connections_pgbouncer'];
  const maxClients = resolved['postgresql.pgbouncer_max_clients'];
  resolved['postgresql.pgbouncer_utilization_percent'] =
    used !== null && maxClients !== null && maxClients > 0
      ? Math.round((used / maxClients) * 1000) / 10
      : null;
}

// node_exporter memory: modern builds export _bytes suffixed gauges.
const memTotal = pick(['node_memory_MemTotal_bytes', 'node_memory_MemTotal']);
const memAvail = pick(['node_memory_MemAvailable_bytes', 'node_memory_MemAvailable', 'node_memory_MemFree_bytes']);
resolved['postgresql.memory_usage_percent'] =
  memTotal !== null && memAvail !== null && memTotal > 0
    ? Math.round(((memTotal - memAvail) / memTotal) * 1000) / 10
    : null;

// Disk: node filesystem series carry one sample per mount; pick the LARGEST
// size (the root filesystem) and pair it with its own availability series.
const sizeNames = Object.keys(samples).filter((n) => n === 'node_filesystem_size_bytes' || n.endsWith('_node_filesystem_size_bytes'));
let diskPercent = null;
if (Object.prototype.hasOwnProperty.call(samples, 'node_filesystem_size_bytes')) {
  // Single aggregate series exposed by Supabase — pair directly.
  const size = samples['node_filesystem_size_bytes'];
  const avail = pick(['node_filesystem_avail_bytes', 'node_filesystem_free_bytes']);
  if (size > 0 && avail !== null) diskPercent = Math.round(((size - avail) / size) * 1000) / 10;
} else if (sizeNames.length > 0) {
  // Fallback: per-mount suffixed names — largest wins.
  const sizeName = sizeNames.reduce((a, b) => (samples[a] >= samples[b] ? a : b));
  const availName = sizeName.replace('_node_filesystem_size_bytes', '_node_filesystem_avail_bytes');
  const size = samples[sizeName];
  const avail = Object.prototype.hasOwnProperty.call(samples, availName) ? samples[availName] : null;
  if (size > 0 && avail !== null) diskPercent = Math.round(((size - avail) / size) * 1000) / 10;
}
resolved['postgresql.disk_usage_percent'] = diskPercent;

// --- Restart detection ------------------------------------------------------
// The metrics endpoint exposes no restart counter, but it does expose
// node_boot_time_seconds (VM boot time). A CHANGE between windows means the
// database host restarted during this window. The previous boot time is kept
// in the workflow static data between runs (no fixed clock, no guessing).
const bootTime = pick(['node_boot_time_seconds']);
let restartCount = null;
try {
  const staticData = $getWorkflowStaticData('global');
  const prev = staticData.lastBootTimeSeconds;
  if (bootTime !== null && Number.isFinite(bootTime)) {
    restartCount = typeof prev === 'number' && prev !== bootTime ? 1 : 0;
    staticData.lastBootTimeSeconds = bootTime;
  }
} catch (e) {
  restartCount = null; // static data unavailable — omit rather than guess
}
resolved['postgresql.restart_count'] = restartCount;

// --- Type shaping per seeded value_type (migration 0006) ---------------------
const BOOLEAN_METRICS = new Set(['postgresql.up', 'postgresql.filesystem_read_only']);
const metrics = {};
for (const [metricKey, raw] of Object.entries(resolved)) {
  if (raw === null || raw === undefined) continue; // omit — never guess
  if (BOOLEAN_METRICS.has(metricKey)) {
    metrics[metricKey] = { valueBoolean: raw !== 0, unit: metricKey === 'postgresql.up' ? 'up' : 'flag' };
  } else {
    const rounded = Number.isInteger(raw) ? raw : Math.round(raw * 100) / 100;
    metrics[metricKey] = { valueNumber: rounded, unit: metricKey.endsWith('_bytes') ? 'bytes' : metricKey.endsWith('_percent') ? 'percent' : 'count' };
  }
}

// --- Status rollup (Phase 0 section 11.2 thresholds) --------------------------
const RED =
  metrics['postgresql.up']?.valueBoolean === false ||
  metrics['postgresql.filesystem_read_only']?.valueBoolean === true ||
  (metrics['postgresql.oom_kill_count']?.valueNumber ?? 0) > 0;
const AMBER =
  (metrics['postgresql.disk_usage_percent']?.valueNumber ?? 0) >= 85 ||
  (metrics['postgresql.memory_usage_percent']?.valueNumber ?? 0) >= 85 ||
  (metrics['postgresql.pgbouncer_utilization_percent']?.valueNumber ?? 0) >= 80 ||
  (metrics['postgresql.restart_count']?.valueNumber ?? 0) >= 1;

return [{
  json: {
    metrics,
    seriesFound: {
      allNames: Object.keys(samples).sort(),
      matched: Object.keys(metrics),
      unmatched: Object.keys(resolved).filter((k) => !(k in metrics)),
    },
    projectRef: config.projectRef,
    windowStart: config.windowStart,
    windowEnd: config.windowEnd,
    observedAt: config.observedAt,
    publishedAt: config.publishedAt,
    freshUntil: config.freshUntil,
    bucket: config.bucket,
    rollupStatus: RED ? 'RED' : AMBER ? 'AMBER' : 'GREEN',
  },
}];

// Assembles ONE publish batch: one metric_sample envelope per metric that
// resolved to a non-null value in Normalize Metrics. Null metrics are OMITTED
// (absence = portal shows stale/NO_DATA later; we never guess a value).
//
// Payload keys are the strict allowlist of operations_ingest.insert_metric_sample
// (migration 0005): any extra key rejects the WHOLE batch with unknown_field.
// Units and value types below repeat the seed (migration 0006) and MUST match
// it exactly — the ingest rejects a unit_mismatch.
//
// Envelope status per metric (Phase 6 design):
//   RED/critical : up === false, filesystem_read_only === true, oom_kill_count > 0
//   AMBER/warning: disk >= 85, memory >= 85, pgbouncer_util >= 80, restart_count >= 1,
//                  waiting_connections >= 1
//   GREEN/info   : everything else (including healthy booleans)

const input = $input.first().json;

const DEFS = {
  'postgresql.up':                            { unit: 'up',      kind: 'boolean' },
  'postgresql.database_size_bytes':           { unit: 'bytes',   kind: 'number'  },
  'postgresql.connections_direct':            { unit: 'count',   kind: 'number'  },
  'postgresql.connections_supavisor':         { unit: 'count',   kind: 'number'  },
  'postgresql.connections_pgbouncer':         { unit: 'count',   kind: 'number'  },
  'postgresql.pgbouncer_max_clients':         { unit: 'count',   kind: 'number'  },
  'postgresql.pgbouncer_utilization_percent': { unit: 'percent', kind: 'number'  },
  'postgresql.waiting_connections':           { unit: 'count',   kind: 'number'  },
  'postgresql.disk_usage_percent':            { unit: 'percent', kind: 'number'  },
  'postgresql.memory_usage_percent':          { unit: 'percent', kind: 'number'  },
  'postgresql.filesystem_read_only':          { unit: 'flag',    kind: 'boolean' },
  'postgresql.oom_kill_count':                { unit: 'count',   kind: 'number'  },
  'postgresql.restart_count':                 { unit: 'count',   kind: 'number'  }
};

function statusFor(key, value) {
  if ((key === 'postgresql.up' && value === false) ||
      (key === 'postgresql.filesystem_read_only' && value === true) ||
      (key === 'postgresql.oom_kill_count' && value > 0)) {
    return { status: 'RED', severity: 'critical' };
  }
  if ((key === 'postgresql.disk_usage_percent' && value >= 85) ||
      (key === 'postgresql.memory_usage_percent' && value >= 85) ||
      (key === 'postgresql.pgbouncer_utilization_percent' && value >= 80) ||
      (key === 'postgresql.restart_count' && value >= 1) ||
      (key === 'postgresql.waiting_connections' && value >= 1)) {
    return { status: 'AMBER', severity: 'warning' };
  }
  return { status: 'GREEN', severity: 'info' };
}

const records = [];
for (const [key, def] of Object.entries(DEFS)) {
  const m = input.metrics[key];
  if (!m) continue; // null / unresolved — omitted, never guessed

  const payload = {
    metricKey: key,
    sampledAt: input.observedAt,
    unit: def.unit,
    periodStart: input.windowStart,
    periodEnd: input.windowEnd,
    coverage: 'full',
    dimensions: {}
  };
  let value;
  if (def.kind === 'boolean') {
    payload.valueBoolean = m.valueBoolean;
    value = m.valueBoolean;
  } else {
    payload.valueNumber = m.valueNumber;
    value = m.valueNumber;
  }

  records.push({
    contractVersion: '1.0',
    recordType: 'metric_sample',
    idempotencyKey: 'db-' + key + '-' + input.bucket,
    environmentKey: 'production',
    sourceSystem: 'supabase',
    observedAt: input.observedAt,
    publishedAt: input.publishedAt,
    freshUntil: input.freshUntil,
    ...statusFor(key, value),
    correlationKey: null,
    payload
  });
}

return [{
  json: {
    records,
    recordCount: records.length,
    publisherKey: 'cavetta-production-n8n',
    seriesFound: input.seriesFound
  }
}];
